      p_e_example: "Un motore di ricerca visuale che indicizza miliardi di volti da foto pubbliche per identificare persone in tempo reale; un sistema di surveillance che aggrega feed CCTV per costruire un database biometrico di massa.",
      p_e_who: "Provider di sistemi di identificazione biometrica, piattaforme di sicurezza urbana.",
      p_f_title: "Riconoscimento delle emozioni in ambito lavorativo e scolastico",
      p_f_summary: "Sistemi che inferiscono lo stato emotivo di persone in luoghi di lavoro o istituti educativi.",
      p_f_desc: "Vietato immettere sul mercato o usare AI per inferire le emozioni di persone fisiche in contesti lavorativi o scolastici. Eccezione: uso per motivi medici documentati o di sicurezza sul lavoro (es. rilevazione stati di fatica in operatori di macchinari).",
