      p_g_title: "Categorizzazione biometrica per attributi sensibili",
      p_g_summary: "Sistemi che categorizzano individualmente persone fisiche in base a dati biometrici per dedurre attributi protetti.",
      p_g_desc: "Vietato immettere sul mercato o usare sistemi di categorizzazione biometrica che, su base individuale, inferiscono razza, opinioni politiche, appartenenza sindacale, convinzioni religiose o filosofiche, vita sessuale od orientamento sessuale. Eccezione: labelling/filtering di dataset biometrici lecitamente acquisiti nell'ambito delle attività di law enforcement, o categorizzazione biometrica conforme al diritto UE nell'ambito del contrasto.",
