// Traduce con fallback: locale richiesto → italiano → la chiave stessa.
export function translate(locale: Locale, ns: string, key: string): string {
  return (
    DICTIONARIES[locale]?.[ns]?.[key] ??
    DICTIONARIES.it?.[ns]?.[key] ??
    key
  );
}
